"use client"

import { CreateOrgForm } from "@/components/auth/create-org-form"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Skeleton } from "@/components/ui/skeleton"
import { useAuthList } from "@/hooks/use-auth-list"
import { authClient } from "@/lib/auth-client"
import { cn } from "@/lib/utils"
import { Building2, Check, ChevronsUpDown, Plus, User } from "lucide-react"
import { useState } from "react"

function OrgAvatar({ name, logo }: { name?: string | null; logo?: string | null }) {
  return (
    <Avatar size="sm" className="rounded-md">
      <AvatarImage src={logo ?? undefined} />
      <AvatarFallback className="rounded-md">
        {name ? name.charAt(0).toUpperCase() : <Building2 className="size-3" />}
      </AvatarFallback>
    </Avatar>
  )
}

export type OrganizationSwitcherProps = {
  className?: string
  /** Hide the "Personal account" entry (active org = null). */
  hidePersonal?: boolean
  /** Hide the "Create organization" action. */
  hideCreate?: boolean
}

/**
 * Dropdown that shows the active organization and lets the user switch between
 * the organizations they belong to, fall back to a personal account, or create
 * a new organization.
 */
export function OrganizationSwitcher({
  className,
  hidePersonal,
  hideCreate,
}: OrganizationSwitcherProps) {
  const { data: orgs, isPending, refetch } = useAuthList(() => authClient.organization.list())
  const { data: activeOrg } = authClient.useActiveOrganization()
  const [createOpen, setCreateOpen] = useState(false)
  const [switching, setSwitching] = useState(false)

  async function setActive(organizationId: string | null) {
    setSwitching(true)
    await authClient.organization.setActive({ organizationId })
    setSwitching(false)
  }

  if (isPending) {
    return <Skeleton className={cn("h-10 w-56 rounded-md", className)} />
  }

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="outline"
            disabled={switching}
            className={cn("h-auto justify-between gap-2 px-2 py-1.5", className)}
          >
            <span className="flex min-w-0 items-center gap-2">
              {activeOrg ? (
                <OrgAvatar name={activeOrg.name} logo={activeOrg.logo} />
              ) : (
                <Avatar size="sm" className="rounded-md">
                  <AvatarFallback className="rounded-md">
                    <User className="size-3" />
                  </AvatarFallback>
                </Avatar>
              )}
              <span className="truncate text-sm font-medium">
                {activeOrg?.name ?? "Personal account"}
              </span>
            </span>
            <ChevronsUpDown className="size-4 shrink-0 text-muted-foreground" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-56">
          <DropdownMenuLabel className="text-xs text-muted-foreground">
            Organizations
          </DropdownMenuLabel>

          {!hidePersonal && (
            <DropdownMenuItem onClick={() => setActive(null)} className="gap-2">
              <Avatar size="sm" className="rounded-md">
                <AvatarFallback className="rounded-md">
                  <User className="size-3" />
                </AvatarFallback>
              </Avatar>
              <span className="flex-1 truncate">Personal account</span>
              {!activeOrg && <Check className="size-4" />}
            </DropdownMenuItem>
          )}

          {orgs?.map((org) => (
            <DropdownMenuItem key={org.id} onClick={() => setActive(org.id)} className="gap-2">
              <OrgAvatar name={org.name} logo={org.logo} />
              <span className="flex-1 truncate">{org.name}</span>
              {activeOrg?.id === org.id && <Check className="size-4" />}
            </DropdownMenuItem>
          ))}

          {!hideCreate && (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => setCreateOpen(true)} className="gap-2">
                <span className="flex size-6 items-center justify-center rounded-md border border-dashed">
                  <Plus className="size-3" />
                </span>
                Create organization
              </DropdownMenuItem>
            </>
          )}
        </DropdownMenuContent>
      </DropdownMenu>

      <Dialog open={createOpen} onOpenChange={setCreateOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create organization</DialogTitle>
            <DialogDescription>Organizations let you collaborate with your team.</DialogDescription>
          </DialogHeader>
          <CreateOrgForm
            onCreated={async (id) => {
              setCreateOpen(false)
              await refetch()
              await setActive(id)
            }}
            onCancel={() => setCreateOpen(false)}
          />
        </DialogContent>
      </Dialog>
    </>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { authClient } from "@/lib/auth-client"
import { cn } from "@/lib/utils"
import { useState, useTransition } from "react"

export function slugify(value: string) {
  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
}

export type CreateOrgFormProps = {
  /** Called with the created organization id after a successful create. */
  onCreated?: (organizationId: string) => void
  /** If provided, renders a Cancel button that calls this. */
  onCancel?: () => void
  className?: string
}

export function CreateOrgForm({ onCreated, onCancel, className }: CreateOrgFormProps) {
  const [name, setName] = useState("")
  const [slugInput, setSlugInput] = useState("")
  const [slugEdited, setSlugEdited] = useState(false)
  const [error, setError] = useState("")
  const [isPending, startTransition] = useTransition()

  const slug = slugEdited ? slugInput : slugify(name)

  function reset() {
    setName("")
    setSlugInput("")
    setSlugEdited(false)
    setError("")
  }

  function handleCancel() {
    reset()
    onCancel?.()
  }

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    if (!name || !slug) return
    setError("")
    startTransition(async () => {
      const { data, error } = await authClient.organization.create({ name, slug })
      if (error) {
        setError(error.message ?? "Failed to create organization")
        return
      }
      reset()
      if (data?.id) onCreated?.(data.id)
    })
  }

  return (
    <form onSubmit={handleSubmit} className={cn("flex flex-col gap-4", className)}>
      <div className="flex flex-col gap-1.5">
        <Label htmlFor="create-org-name">Name</Label>
        <Input
          id="create-org-name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Acme Inc."
          autoFocus
          disabled={isPending}
          required
        />
      </div>
      <div className="flex flex-col gap-1.5">
        <Label htmlFor="create-org-slug">Slug</Label>
        <Input
          id="create-org-slug"
          value={slug}
          onChange={(e) => {
            setSlugInput(slugify(e.target.value))
            setSlugEdited(true)
          }}
          placeholder="acme"
          disabled={isPending}
          required
        />
      </div>
      {error && <p className="text-sm text-destructive">{error}</p>}
      <div className="flex justify-end gap-2">
        {onCancel && (
          <Button type="button" variant="outline" onClick={handleCancel} disabled={isPending}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isPending}>
          {isPending ? "Creating…" : "Create"}
        </Button>
      </div>
    </form>
  )
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"

/**
 * Fetch-on-mount helper for Better Auth list endpoints, without TanStack Query.
 *
 * Runs `fetcher` once on mount and exposes `refetch` for manual refresh after a
 * mutation. The fetcher is read through a ref so a new inline closure each
 * render does not retrigger the effect.
 *
 * @param fetcher - Returns a Better Auth response shaped as `{ data }`.
 */
export function useAuthList<T>(fetcher: () => Promise<{ data: T | null }>) {
  const fetcherRef = useRef(fetcher)
  useEffect(() => {
    fetcherRef.current = fetcher
  })

  const [data, setData] = useState<T | null>(null)
  const [isPending, setIsPending] = useState(true)

  const refetch = useCallback(async () => {
    setIsPending(true)
    const { data } = await fetcherRef.current()
    setData(data ?? null)
    setIsPending(false)
  }, [])

  useEffect(() => {
    let active = true
    fetcherRef.current().then(({ data }) => {
      if (!active) return
      setData(data ?? null)
      setIsPending(false)
    })
    return () => {
      active = false
    }
  }, [])

  return { data, isPending, refetch }
}
